from http import HTTPStatus
def raise_for_status(code):
    if code >= 400:
        phrase = HTTPStatus(code).phrase
        raise RuntimeError('%d %s' % (code, phrase))
for code in (200, 404, 500):
    try:
        raise_for_status(code)
        print(code, 'fine')
    except RuntimeError as err:
        print(code, 'stopped:', err)

import os, tempfile
body = b'To be, or not to be, that is the question.'
def iter_content(data, size):
    for start in range(0, len(data), size):
        yield data[start:start + size]
with tempfile.TemporaryDirectory() as folder:
    with open(os.path.join(folder, 'speech.txt'), 'wb') as file:
        for chunk in iter_content(body, 16):
            print(file.write(chunk))

import xml.etree.ElementTree as ET
root = ET.fromstring('<body><p>one</p><p>two</p></body>')
def find_elements(path):
    return root.findall(path)
def find_element(path):
    return find_elements(path)[0]
print(len(find_elements('.//p')), find_element('.//p').text)
print(find_elements('.//h1'))
try:
    find_element('.//h1')
except IndexError:
    print('Result: find_element fails when nothing matches')

from contextlib import nullcontext
class Page:
    def goto(self, url):
        print('visiting', url)
    def locator(self, css):
        return 'element ' + css
class Playwright:
    def new_page(self):
        return Page()
with nullcontext(Playwright()) as p:
    page = p.new_page()
    page.goto('https://example.com/')
    print(page.locator('h1'))

looks = [None, None, 'Hello']  # what each look sees
def locator_text(limit):
    for look, text in enumerate(looks[:limit], 1):
        if text is not None:
            return 'found %r on look %d' % (text, look)
    return 'timeout after %d looks' % limit
print(locator_text(5))
print(locator_text(2))
